def protected_division(x1, x2):
    if x2 == 0:
        return 1
    else:
        return x1 / x2

def protected_sqrt(x):
    if x < 0:
        return 0
    else:
        return np.sqrt(x)

def protected_log(x):
    if x <= 0:
        return 0
    else:
        return np.log(x)
